static inline void tng_set_window_icon(SDL_Window *window)
{
    SDL_Surface *icon = SDL_CreateSurfaceFrom(TNG_ICON_SIZE, TNG_ICON_SIZE,
                                              SDL_PIXELFORMAT_RGBA32,
                                              (void *)tng_icon_rgba,
                                              TNG_ICON_SIZE * 4);
    if (icon) {
        SDL_SetWindowIcon(window, icon);
        SDL_DestroySurface(icon);
    }
}

